    var xed = !appMade && XEDIT.test(ty) && (ty !== 'stk' || /^(move|make|jobout|jobin)$/.test(d.kind || ''));
    var row = function (k, v) { return v ? '<tr><th scope="row">' + esc(T(k)) + '</th><td>' + v + '</td></tr>' : ''; };
