        d.ch = { bsr: bsr, serial: chn, date: val('ax-chdate') || date, minor: val('ax-minor'), sal: $('#ax-chsal') ? $('#ax-chsal').checked : false };
        if (rec && rec.alloc) d.alloc = rec.alloc;
