    SE: { as: 'export', kind: 'expwop', head: 'gstsb3', line: 'gstsbdt3' },
    P9: { as: 'buy', head: 'gstpb', line: 'gstpbdt' }, P8: { as: 'buy', head: 'gstpb2', line: 'gstpbdt2' },
    RS: { as: 'sret', head: 'gstsr', line: 'gstsrdt' }, D8: { as: 'sret', head: 'gstsr2', line: 'gstsrdt2' },
