  function ok(s) { var d = pd(s); return !!d && iso(d) === s; }
  function addDays(s, n) { var d = pd(s); d.setUTCDate(d.getUTCDate() + n); return iso(d); }
  function lastDom(y, m) { return new Date(Date.UTC(y, m + 1, 0)).getUTCDate(); }
