      l = l.trim(); var m = /^(\d{4})-(\d{1,2})-(\d{1,2})\s*(.*)$/.exec(l), s = '', nm = '';
      if (m) { s = m[1] + '-' + ('0' + m[2]).slice(-2) + '-' + ('0' + m[3]).slice(-2); nm = m[4]; }
      else if ((m = /^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{4})\s*(.*)$/.exec(l))) { s = m[3] + '-' + ('0' + m[2]).slice(-2) + '-' + ('0' + m[1]).slice(-2); nm = m[4]; }
      if (s && ok(s)) h[s] = nm.replace(/^[-–:,\s]+/, '') || 'Holiday';
