      var A = L[1].slice(1), B = L[2].slice(1), r = compare(A, B, c1.keys, c2.keys, c1.am, c2.am, o), H1 = L[1][0], H2 = L[2][0], useAm = c1.am >= 0 && c2.am >= 0;
