  /* ================= pure part (also used by scripts/test_ft-courtfee.js) ================= */
  var BY = {}; STATES.forEach(function (s) { BY[s.k] = s; });
  function r4(x) { return Math.round(x * 10000) / 10000; }
  function band(s, v) {
    var B = s.adv.bands;
    for (var i = 0; i < B.length; i++) { var b = B[i]; if ((v > b[0] || (i === 0 && v > 0)) && (b[1] == null || v <= b[1])) return i; }
    return -1;
  }
  /* returns { fee, raw, band, steps:[text], capped, unsure:[a,b] } or null when the state has no fee table */
  function calc(key, v) {
    var s = BY[key]; v = +v; if (!s || !s.adv || !(v > 0) || !isFinite(v)) return null;
    var i = band(s, v); if (i < 0) return null;
    var b = s.adv.bands[i], ex = v - b[0], fee = b[2], L = [];
    L.push(b[1] == null ? 'Value above ₹' + rs(b[0]) + ' (last band, no upper end).' : 'Value from ₹' + rs(b[0]) + ' up to ₹' + rs(b[1]) + '.');
    L.push('Fee at the start of the band: ₹' + rs(b[2]) + '.');
    if (b[5] != null) { var p = r4(ex * b[5] / 100); fee += p; L.push(b[5] + '% of ₹' + rs(r4(ex)) + ' (the part above ₹' + rs(b[0]) + ') = ₹' + rs(p) + '.'); }
    if (b[3] != null) { var n = Math.ceil(ex / b[3] - 1e-9); var q = r4(n * b[4]); fee += q; L.push(n + ' step' + (n === 1 ? '' : 's') + ' of ₹' + rs(b[3]) + ' (a part of a step counts as a full step) × ₹' + rs(b[4]) + ' = ₹' + rs(q) + '.'); }
    fee = r4(fee);
    var raw = fee, capped = false, unsure = null;
    if (s.adv.min && fee < s.adv.min) { fee = s.adv.min; L.push('Smallest fee: ₹' + rs(s.adv.min) + '.'); }
    if (s.adv.max != null && fee > s.adv.max) { fee = s.adv.max; capped = true; L.push('The Act limits the fee to ₹' + rs(s.adv.max) + '.'); }
    if (s.adv.capAlt && fee > s.adv.capAlt[0]) unsure = [s.adv.capAlt[0], Math.min(fee, s.adv.capAlt[1])];
    if (s.adv.round === 'up1' && fee % 1) { var lo = fee % 1 < 0.5; fee = Math.ceil(fee - 1e-9); L.push('A part of a rupee counts as one rupee: ₹' + rs(fee) + '.' + (lo ? ' (The section’s heading says "nearest rupee", so a court may take ₹' + rs(fee - 1) + '.)' : '')); }
    if (b[6]) L.push(b[6]);
    return { fee: fee, raw: raw, band: i, steps: L, capped: capped, unsure: unsure };
  }
  function rs(n) { return (+n || 0).toLocaleString('en-IN', { maximumFractionDigits: 4 }); }
  W.NSFtCourtFee = { STATES: STATES, BY: BY, calc: calc };

