              return p2.then(function () { off += buf.byteLength; sent += buf.byteLength; bar(i, off, f.size); var T = $('[data-ptot]', box()); if (T) T.textContent = 'Sending… ' + kb(sent) + ' of ' + kb(total) + speed(sent, t0); return more(); });
