    function afterBtns() { return '<div class="pr-bar">' + (SD.role === 'host' ? '<label class="btn" for="fs-sd-file">Send more files</label>' : '') + '<button type="button" class="btn" data-bye>Disconnect</button></div>'; }
    /* ---- receiver ---- */
