  function sellForm(a) {
    var sale = a.sale || { date: today(), mode: 'bank' };
    open(T('sellt', { n: a.name }), '<div class="fg">' + fld('fs-date', A.T('date'), inp('fs-date', sale.date, { type: 'date', req: 1 })) +
      fld('fs-amt', T('saleprice'), inp('fs-amt', sale.amount || '', { mode: 'decimal', req: 1 })) + fld('fs-gst', T('salegst'), inp('fs-gst', sale.gstAmt || '', { mode: 'decimal' }), { hint: T('salegsth') }) +
      fld('fs-mode', T('recdby'), sel('fs-mode', sale.mode, modeOpts(true))) + fld('fs-party', T('buyer'), inp('fs-party', sale.buyer && sale.buyer.name || '', { list: 'b2-parties' })) +
      '</div><p class="soft" data-bv aria-live="polite"></p>' + dl('b2-parties', partyNames()),
    function () {
      var date = val('fs-date'), amt = r2(num(val('fs-amt'))), mode = val('fs-mode'), party = val('fs-party');
      if (!need(date, A.T('date')) || !lockOk(date, a.sale) || date < a.date) return;
      if (mode === 'credit' && !need(party, T('buyer'))) return;
      var d = Object.assign(a.sale ? JSON.parse(JSON.stringify(a.sale)) : { type: 'fa', kind: 'sale', app: 1 }, { asset: a.id, name: a.name, date: date, amount: amt, gstAmt: r2(num(val('fs-gst'))), mode: mode, buyer: { name: party }, bv: faBook(a, date), seller: sellerCopy(), no: '' });
      d.total = r2(amt + d.gstAmt);
      NSStore.put('doc', d).then(function () { dlg.close(); NS.toast(A.T('saved')); A.show(); });
    }, function () {
      function bv() { var dt = val('fs-date'); $('[data-bv]', form).textContent = dt && dt >= a.date ? T('bvon', { a: money(X.bookValueOn(a, dt)), d: A.ldate(dt) }) : ''; }
      $('#fs-date', form).addEventListener('change', bv); bv();
    });
  }
  /* the day depreciation is worked out to: the end of the chosen period when it falls in the year, else today, never past 31 March */
  function depDefault(fy) {
    var s = X.fyStart(fy), e = X.fyEnd(fy), r = A.range ? A.range() : [], d = r[1] && r[1] >= s && r[1] <= e ? r[1] : today();
    return d < s ? s : d > e ? e : d;
  }
  /* post book depreciation up to the chosen day, dated that day (pro rata by days; whatever was posted before is taken off) */
  function postDep(fy) {
    var inp = $('#b2-depto'), date = inp && inp.value || depDefault(fy);
    if (date < X.fyStart(fy) || date > X.fyEnd(fy)) { NS.toast(NS.t('fx.dep_out', { fy: fy }), 'bad'); return; }
    var R = X.register(A.data().doc, A.bizName(), fy, date);
    if (!R.post.length) { NS.toast(NS.t('fx.dep_none', { d: A.ldate(date) })); return; }
    if (!lockOk(date)) return;
    var msg = NS.t('fx.dep_q', { a: money(R.tot.todo), d: A.ldate(date), fy: fy });
    (NS.ask ? NS.ask(msg) : Promise.resolve(window.confirm(msg))).then(function (yes) {
      if (!yes) return;
      var full = date === X.fyEnd(fy), d = { type: 'jv', app: 1, dep: fy, date: date, no: nextNo('jv', 'JV', date),
        narr: 'Depreciation for FY ' + fy + (full ? '' : ' up to ' + A.ldate(date)) + ' (Companies Act 2013, Schedule II)', seller: sellerCopy(), lines: R.post.map(function (l) { return { a: l.a, dr: l.dr, cr: l.cr }; }) };
      d.total = jvTotal(d);
      NSStore.put('doc', d).then(function () { NS.toast(A.T('saved')); A.show(); });
    });
  }

  /* ---------- year end ---------- */
  A.addSection('b2year', function () {
    var D = A.data().doc, first = A.mine().reduce(function (f, d) { return d.date && (!f || d.date < f) ? d.date : f; }, '');
    var Ys = A.years ? A.years() : {}, f0 = first ? X.fyOf(first) : ''; if (Ys.first && (!f0 || Ys.first < f0)) f0 = Ys.first;   /* SQLite Stage 3: closed years are not read at start, but stay in the list */
    var picker = fyPick(f0), fy = fySel, Y = X.yearSummary(D, items(), A.bizName(), fy), closed = X.isClosed(cfg().closed, A.biz() || A.bizName(), X.fyStart(fy));
    var tiles = [['sales', Y.pl.rev], ['gp', Y.pl.gross], ['np', Y.pl.profit], ['cash', Y.cash], ['bank', Y.bank], ['recv', Y.recv], ['pay', Y.pay], ['stock', Y.stock.value]];
    return '<div class="pane-hd"><h2>' + esc(T('year')) + '</h2>' + (closed ? '<span class="pill ok">' + esc(T('isclosed')) + '</span>' : '') + '</div><p class="soft">' + esc(T('yearh')) + '</p>' + picker +
      '<div class="tbl-wrap" dir="ltr"><div lang="en-IN" class="stsheet" data-sheet>' + head('Year-end summary', 'FY ' + fy + ' (' + A.ldate(Y.from) + ' to ' + A.ldate(Y.to) + ')') +
      '<div class="tiles">' + tiles.map(function (x) { var nl = x[0] === 'np' && x[1] < 0; return '<div class="tile' + (x[1] < 0 ? ' neg' : '') + '"><span>' + esc(T(nl ? 'y_nl' : 'y_' + x[0])) + '</span><b>' + money(nl ? -x[1] : x[1]) + '</b></div>'; }).join('') + '</div>' + foot() + '</div></div>' +
      '<div class="card"><h3>' + esc(T('checks')) + '</h3>' + (Y.checks.length ? '<ul>' + Y.checks.map(function (c) {
        return '<li>' + esc(T('ck_' + c[0], { n: c[0] === 'dep' || c[0] === 'diff' ? money(Math.abs(c[1])) : c[1] })) + (c[0] === 'dep' ? ' <a href="#b2fa">' + esc(T('fa')) + ' ›</a>' : c[0] === 'neg' ? ' <a href="#b2gd">' + esc(T('gd')) + ' ›</a>' : '') + '</li>'; }).join('') + '</ul>' : '<p class="soft">' + esc(T('ck_ok')) + '</p>') + '</div>' +
      '<div class="card"><h3>' + esc(T('nextyear', { fy: X.nextFy(fy) })) + '</h3><p>' + esc(T('carryh')) + '</p><p>' + esc(T('numh')) + '</p></div>' +
      '<div class="card"><h3>' + esc(T('closet')) + '</h3><p>' + esc(T(closed ? 'reopenh' : 'closeh')) + '</p><p class="soft">' + esc(T('fasth')) + '</p><div class="quick">' +
        '<button type="button" class="btn' + (closed ? '' : ' primary') + '" data-b2close="' + fy + '">' + esc(T(closed ? 'reopen' : 'close', { fy: fy })) + '</button>' +
        '<button type="button" class="btn" data-b2print>' + esc(A.T('print')) + '</button></div></div>' +
      '<div class="card"><h3>' + esc(T('newfile')) + '</h3><p>' + esc(T('newfileh')) + '</p><button type="button" class="btn" data-b2cf="' + fy + '">' + esc(T('cfdl', { fy: X.nextFy(fy) })) + '</button></div>';
  }, wireAll);
  /* ERP Round 1 (A-4, C-1, C-18): a year is closed under the business id ('#<id>'); reopening asks the PIN (when set) and a reason, both logged */
  function toggleClose(fy) {
    var bz = A.biz() || { name: A.bizName() }, b = bz.id ? '#' + bz.id : key(A.bizName()), shut = X.isClosed(cfg().closed, bz, X.fyStart(fy));
    var ask = shut ? NS.guard({ title: NS.t('au.reopent', { fy: fy }), msg: NS.t('au.reopenp'), why: 'need' }) : Promise.resolve(NS.okSync(T('closeq', { fy: fy })) ? { why: '' } : null);
    ask.then(function (g) {
      if (!g) return;
      return saveCfg(function (c) {
        c.closed = c.closed || {};
        if (shut) X.closedKeys(bz).forEach(function (k) { if (c.closed[k]) c.closed[k] = c.closed[k].filter(function (x) { return x !== fy; }); });
        else { var l = c.closed[b] = c.closed[b] || []; if (l.indexOf(fy) < 0) l.push(fy); }
      }, { why: g.why }).then(function () { NS.toast(T(shut ? 'reopened' : 'closed', { fy: fy })); A.show(); });
    }, function () {});
  }
  function carry(fy) {
    var C = A.data(), recs = X.carryForward(C.doc, C.item, A.bizName(), fy, sellerCopy()), now = Date.now();
    recs.forEach(function (r) { r.created = r.updated = now; });
    var strip = function (l) { return JSON.parse(JSON.stringify(l)); };
    var file = { app: 'Nivesh Sahayak', kind: 'backup', version: 1, saved: new Date().toISOString(), note: 'Opening balances for FY ' + X.nextFy(fy) + ' carried forward from FY ' + fy,
      data: { biz: strip(C.biz.filter(function (b) { return b.id === biz().id; })), party: strip(C.party), item: strip(C.item), doc: recs } };
    download('nivesh-sahayak-opening-' + X.nextFy(fy) + '.json', JSON.stringify(file, null, 1), 'application/json');
    NS.toast(T('cfdone', { n: recs.length }));
  }

  /* ---------- godowns and stock transfer ---------- */
  function gdNames() { var o = {}; (cfg().godowns || []).forEach(function (g) { if (g) o[key(g)] = g; }); A.mine().forEach(function (d) { (d.type === 'stk' ? [d.gd, d.from, d.to] : [d.gd]).forEach(function (g) { if (g) o[key(g)] = o[key(g)] || g; }); }); return Object.keys(o).map(function (k) { return o[k]; }).filter(function (g) { return key(g) !== S.MAIN; }).sort(); }
  function gdLabel(g) { return g ? g : T('main'); }
  var gdView = '';
