        '</tbody><tfoot><tr><th>Total</th>' + TR.all.map(function (v) { return '<th class="n">' + money(v, false) + '</th>'; }).join('') + '<th class="n">' + money(TR.all.reduce(function (s, v) { return s + v; }, 0), false) + '</th><th></th></tr></tfoot></table>';
