  function partnerNames(kind) { return kind === 'capin' || kind === 'drw' ? ((A.biz() || {}).partners || []).map(function (p) { return String(p && p.name || '').trim(); }).filter(Boolean) : []; }
  var KINDS = ['capin', 'drw', 'loanin', 'loanout', 'givenout', 'givenin'];
