    ['gstin', 'addr', 'city', 'pin', 'phone', 'bankName', 'bankAcc', 'bankIfsc', 'upi', 'logo'].forEach(function (k) { var v = String(S[k] || '').trim(); if (v) r[k] = v; else delete r[k]; });
    var R = rec(S.kind, S.reg, S.btype), on = S.sw || R, sw = {};
