      note.innerHTML = '<b>' + esc(t('banner')) + '</b>' + (bad.length ? '<ul>' + bad.map(function (c) { return '<li>' + esc(checkLine(c).text) + '</li>'; }).join('') + '</ul>' : '');
      form.insertBefore(note, form.firstChild);
