          open.map(function (b) { return '<option value="' + esc(b.id) + '"' + (x.bill && x.bill.id === b.id ? ' selected' : '') + '>' + esc(b.no + ' · ' + b.party + ' · ' + money(b.left) + ' due') + '</option>'; }).join('') + '</select>';
