      var b = bs.filter(function (y) { return y.id === cfg.defBiz; })[0] || bs[0];
      if (b.state) P.state = String(b.state).slice(0, 2);
      if (b.reg === 'comp') P.gst = 'comp'; else if (b.reg === 'unreg') P.gst = 'none'; else if (P.gst === 'comp' || P.gst === 'none') P.gst = 'monthly';
      FROM = b.name || '';
