    mine(docs, biz).forEach(function (d) { var n = String(d.no || ''); if (n.indexOf(head) === 0) { var v = parseInt(n.slice(head.length), 10); if (v > mx) mx = v; } });
    return head + String(mx + 1).padStart(3, '0');
